      games: {}, // minigame id ("challenge"/"chrono"/"truefalse"/"whosaid") -> { date, played, won } for today's tile checkmarks + the daily-sweep badge
      intro: { date: "", count: 0, extra: 0 }, // new cards introduced today (+ today's Custom-study bump)
