      ok: true, done: false, seqs: usable, train: train, test: test, reviews: n,
      w: FSRS_PARAMS.slice(), best: FSRS_PARAMS.slice(), bestLoss: Infinity,
      m: FSRS_PARAMS.map(() => 0), v: FSRS_PARAMS.map(() => 0),
