  async function cardStatsFlush() {
    if (_cardStatsT) { clearTimeout(_cardStatsT); _cardStatsT = null; }
    const pend = _cardStatsPend;
    if (!Object.keys(pend).length) return;
    _cardStatsPend = Object.create(null);   // taken BEFORE the await, so a grade mid-flight joins the next batch
    const rows = Object.keys(pend).map((id) => ({ card_id: id, a: pend[id].a, h: pend[id].h, g: pend[id].g, e: pend[id].e }));
    const r = await supaFetch("/rest/v1/rpc/bump_card_grades", { method: "POST", body: { rows: rows } });
    // 404 = the schema block has not been run on this project. Stop asking rather than posting on every
    // grade for ever; the site is entirely usable without it.
    if (r.status === 404) _cardStatsOff = true;
  }
  function cardStatsRead() {
    try {
      const raw = JSON.parse(localStorage.getItem(CARD_STATS_KEY) || "null");
      if (raw && raw.d === todayStr() && raw.s && typeof raw.s === "object") return raw.s;
    } catch (e) {}
    return null;
  }
  async function cardStatsLoad() {
    if (isDevOrigin()) return;                       // the dev machine has no traffic to pool
    const cached = cardStatsRead();
    if (cached) { CARD_STATS = cached; return; }
    const out = Object.create(null);
    for (let from = 0; ; from += SUPA_PAGE) {
      const r = await supaFetch("/rest/v1/card_stats?select=card_id,a,h,g,e", {
        auth: false, headers: { Range: from + "-" + (from + SUPA_PAGE - 1) },
      });
      if (r.status === 404) { _cardStatsOff = true; return; }
      if (!r.ok || !Array.isArray(r.data)) return;   // offline, or a project without the block: keep the editorial rating
      r.data.forEach((row) => { if (row && row.card_id) out[row.card_id] = { a: row.a || 0, h: row.h || 0, g: row.g || 0, e: row.e || 0 }; });
      if (r.data.length < SUPA_PAGE) break;
    }
    CARD_STATS = out;
    try { localStorage.setItem(CARD_STATS_KEY, JSON.stringify({ d: todayStr(), s: out })); } catch (e) {}
  }
  window.addEventListener("pagehide", () => { cardStatsFlush(); });

  function dueCountNow() {
    return activeCardIds().filter((id) => isDueNow(id) && !isSuspended(id) && !isBuried(id)).length;
  }

  /* ============================================================
     COMMUNITY DECKS — decks the user writes themselves

     Phase 1 is entirely local: decks live in this device's IndexedDB and travel as JSON files. There is
     no server, no account and no publishing yet (see docs/user-decks-plan.md for the later phases).

     The store is deliberately SEPARATE from CARDS / TREE / window.GLOSSARY / ADMIN_EDITS — see the note
     on UCARDS at the top of the file for the four existing behaviours that force that separation. The
     bridges into the rest of the app are narrow and all in one place: entryCardIds / availableCardIdSet /
     buildSession / cardById.
     ============================================================ */
  const UDECK_DB = "folio-community", UDECK_STORE = "decks", UNOTE_STORE = "notes";
  const UDECK_LS_KEY = "folio_community_v1";   // fallback store — see communityUseLS below
  const UDECK_FORMAT = 1;                       // export-file version
  /* The STORE's own shape version, which is not the export file's and must not be confused with it: a deck
     FILE has looked the same throughout and still does, while `fmt` says whether a record on this device
     keeps its cards inline (1, everything before Aug 2026) or in the `notes` store beside it (2). A record
     with no `fmt` is a 1 and is migrated on the next boot — see uDeckSplitLegacy. */
  const UDECK_FMT = 2;
  let _communityLS = false;                     // true once we know IndexedDB is unusable here
  let _communityReady = false;

  function uid(n) {
    let s = "";
    const abc = "abcdefghijklmnopqrstuvwxyz0123456789";
    const rnd = (window.crypto && window.crypto.getRandomValues) ? window.crypto.getRandomValues(new Uint32Array(n)) : null;
    for (let i = 0; i < n; i++) s += abc[(rnd ? rnd[i] : Math.floor(Math.random() * 4294967296)) % abc.length];
    return s;
  }
  /* ---------- SUBDECKS (Aug 2026, on request) ----------
     A community deck may group its cards into subdecks, so one file can hold what would otherwise be two
     decks — an HSK deck with a direction each way, a course with a chapter each. Each is studiable and
     addable on its own, exactly as a curated collection's decks are.

     A subdeck is a STRING ON THE CARD (`card.sub`, the subdeck's own title) and there is no list beside it:
     the deck's subdecks are the distinct values in card order. That is the whole design decision, and it is
     what makes the feature cost NO schema change — the title rides on each card, so it survives export,
     import, publish and install through paths that already carry the card whole. An explicit list would
     have needed a column on `user_decks`, which is exactly the migration card types are still waiting on.
     What it gives up is an EMPTY subdeck, and ordering the subdecks independently of the cards; neither is
     worth a blocked feature. Renaming one is rewriting `sub` on its cards.

     An entry id is `u:<deckId>` for the whole deck and `u:<deckId>/<title>` for one subdeck. A deck id is
     [a-z0-9]{4,16} and so can never contain the slash, which is what makes the split unambiguous; the title
     is percent-encoded after it. Everything that only wants the DECK keeps calling uDeckIdOf and is
     unchanged — it strips the suffix — and only the handful of places that must narrow call uSubOf. */
  /* `#` after the path names a CARD TEMPLATE — see uTplOf. It is declared here because uDeckIdOf reads it,
     and it is safe as a RAW separator for the reason the `/` above is: `uSubEntry` percent-encodes the
     whole path and encodeURIComponent escapes `#` to %23, so a subdeck titled "C#" cannot forge one. `~`
     would NOT have done: it is in the unreserved set and travels through the encoder untouched. */
  const SUB_TPL = "#";
