      front: uSH(String((raw && raw.front) == null ? "" : raw.front)).slice(0, UTYPE_TPL_MAX),
      back: uSH(String((raw && raw.back) == null ? "" : raw.back)).slice(0, UTYPE_TPL_MAX),
