  const CARD_COLORS = [{ k: "red", h: "#d8453c" }, { k: "amber", h: "#e0982b" }, { k: "green", h: "#3a9d5b" }, { k: "blue", h: "#3a6ea8" }, { k: "purple", h: "#8a5cc4" }, { k: "slate", h: "#64748b" }];
  const COLOR_HEX = Object.fromEntries(CARD_COLORS.map((c) => [c.k, c.h]));
