    let far = 1, fd = -1;
    for (let i = 1; i < n; i++) { const dx = pts[i][0] - pts[0][0], dy = pts[i][1] - pts[0][1], d = dx * dx + dy * dy; if (d > fd) { fd = d; far = i; } }
    const a = dpSimplify(pts.slice(0, far + 1), eps), b = dpSimplify(pts.slice(far).concat([pts[0]]), eps);
