      const mark = [];
      for (let y = 0; y < TH; y++) for (let x = 0; x < TW; x++) { const i = y * TW + x; if (key[i] < 0) continue;
        if ((x > 0 && key[i - 1] === LINE) || (x < TW - 1 && key[i + 1] === LINE) || (y > 0 && key[i - TW] === LINE) || (y < TH - 1 && key[i + TW] === LINE)) mark.push(i);
      }
